// ── Music Player ───────────────────────────────────────────────────────────
// Reads playlist from audio/playlist.json (generated by generate-playlist.sh)
// so you never need to hardcode track names in JS.

(function () {
    const audio = document.getElementById('bg-audio');
    const playBtn = document.getElementById('mp-play');
    const prevBtn = document.getElementById('mp-prev');
    const nextBtn = document.getElementById('mp-next');
    const titleEl = document.getElementById('mp-title');
    const bar = document.getElementById('mp-bar');
    const curTimeEl = document.getElementById('mp-current');
    const durTimeEl = document.getElementById('mp-duration');
    const volumeBar = document.getElementById('mp-volume');
    const volumeBtn = document.getElementById('mp-volume-btn');

    if (!audio || !playBtn || !bar || !titleEl) return;

    let PLAYLIST = [];
    let index = 0;
    let lastVolume = 0.8;

    // ── Clean up the display title from filename ──
    function cleanTitle(raw) {
        return raw
            .replace(/\.(mp3|wav|ogg|m4a|flac)$/i, '')            // strip extension
            .replace(/^\d+\s*[-–.]\s*/, '')                        // strip leading "01 - " order prefix
            .replace(/\s*\((?:lyrics?|official|audio|video|mv)\)\s*/gi, '')  // strip common tags
            .trim();
    }

    function formatTime(sec) {
        if (!isFinite(sec)) return '0:00';
        const m = Math.floor(sec / 60);
        const s = Math.floor(sec % 60).toString().padStart(2, '0');
        return `${m}:${s}`;
    }

    function updatePlayIcon() {
        playBtn.innerHTML = audio.paused ? '<i class="fa-solid fa-play"></i>' : '<i class="fa-solid fa-pause"></i>';
        playBtn.setAttribute('aria-label', audio.paused ? 'Play' : 'Pause');
    }

    function updateVolumeIcon() {
        if (!volumeBtn) return;
        let icon = 'fa-volume-high';
        if (audio.muted || audio.volume === 0) icon = 'fa-volume-xmark';
        else if (audio.volume < 0.5) icon = 'fa-volume-low';
        volumeBtn.innerHTML = `<i class="fa-solid ${icon}"></i>`;
        volumeBtn.setAttribute('aria-label', audio.muted || audio.volume === 0 ? 'Unmute' : 'Mute');
    }

    function updateVolumeFill() {
        if (!volumeBar) return;
        volumeBar.style.backgroundSize = `${audio.volume * 100}% 100%`;
    }

    function loadTrack(i, autoplay) {
        if (PLAYLIST.length === 0) return;
        index = (i + PLAYLIST.length) % PLAYLIST.length;
        const track = PLAYLIST[index];
        audio.src = track.src;
        titleEl.textContent = track.displayTitle;
        bar.value = 0;
        bar.max = 0;
        bar.style.backgroundSize = '0% 100%';
        curTimeEl.textContent = '0:00';
        durTimeEl.textContent = '0:00';
        if (autoplay) audio.play().catch(() => {});
    }

    // ── Fetch playlist.json then wire up everything ──
    fetch('audio/playlist.json')
        .then(res => res.json())
        .then(tracks => {
            PLAYLIST = tracks.map(t => ({
                src: t.src,
                displayTitle: cleanTitle(t.title)
            }));

            if (PLAYLIST.length === 0) return;

            // Load first track (don't play — curtain.js handles that)
            loadTrack(0, false);

            updatePlayIcon();
            updateVolumeIcon();
            updateVolumeFill();
        })
        .catch(err => {
            console.warn('Could not load playlist.json:', err);
            titleEl.textContent = 'No tracks found';
        });

    // ── Controls ──
    playBtn.addEventListener('click', () => {
        if (audio.paused) audio.play().catch(() => {});
        else audio.pause();
    });

    prevBtn?.addEventListener('click', () => loadTrack(index - 1, true));
    nextBtn?.addEventListener('click', () => loadTrack(index + 1, true));

    audio.addEventListener('loadedmetadata', () => {
        bar.max = audio.duration || 0;
        durTimeEl.textContent = formatTime(audio.duration);
    });

    audio.addEventListener('timeupdate', () => {
        bar.value = audio.currentTime;
        curTimeEl.textContent = formatTime(audio.currentTime);
        const pct = audio.duration ? (audio.currentTime / audio.duration) * 100 : 0;
        bar.style.backgroundSize = `${pct}% 100%`;
    });

    bar.addEventListener('input', () => { audio.currentTime = Number(bar.value); });
    audio.addEventListener('ended', () => loadTrack(index + 1, true));
    audio.addEventListener('play', updatePlayIcon);
    audio.addEventListener('pause', updatePlayIcon);

    if (volumeBar) {
        audio.volume = 0.8;
        volumeBar.value = 0.8;
        volumeBar.addEventListener('input', () => {
            audio.muted = false;
            audio.volume = Number(volumeBar.value);
            if (audio.volume > 0) lastVolume = audio.volume;
            updateVolumeIcon();
            updateVolumeFill();
        });
    }

    volumeBtn?.addEventListener('click', () => {
        if (audio.muted || audio.volume === 0) {
            audio.muted = false;
            audio.volume = lastVolume || 0.8;
            if (volumeBar) volumeBar.value = audio.volume;
        } else {
            lastVolume = audio.volume;
            audio.muted = true;
            if (volumeBar) volumeBar.value = 0;
        }
        updateVolumeIcon();
        updateVolumeFill();
    });

    updatePlayIcon();
    updateVolumeIcon();
    updateVolumeFill();
})();
